{"command":"python3 - << 'PY'
import pty, os, subprocess, time, select

def run_with_pty(args):
    master, slave = pty.openpty()
    proc = subprocess.Popen(args, stdin=slave, stdout=slave, stderr=slave, close_fds=True)
    os.close(slave)
    # give time
    time.sleep(0.6)
    try:
        proc.wait(timeout=1)
    except:
        proc.terminate()
        try:
            proc.wait(timeout=1)
        except:
            proc.kill()
    data=b''
    while True:
        r,_,_ = select.select([master], [], [], 0.1)
        if not r:
            break
        try:
            chunk=os.read(master, 4096)
            if not chunk:
                break
            data+=chunk
        except Exception as e:
            break
    os.close(master)
    return data, proc.returncode

for m in ["ansible","download"]:
    data, rc = run_with_pty(["./executable","-m",m,"--speed-factor","10","--exit-after-time","200ms"])
    print(f"{m} rc={rc} len={len(data)}")
    print(data[:800])

# Also test botnet with pty vs not
for m in ["botnet","cc"]:
    data, rc = run_with_pty(["./executable","-m",m,"--speed-factor","100","--exit-after-time","200ms","--instant-print-lines","2"])
    print(f"{m} pty rc={rc} len={len(data)} head={data[:500]}")
