import pty, os, subprocess, time, select, struct, fcntl, termios

# Set winsize manually
def run_with_pty_winsize(args, rows=24, cols=80):
    master, slave = pty.openpty()
    # set winsize
    winsize = struct.pack("HHHH", rows, cols, 0, 0)
    fcntl.ioctl(slave, termios.TIOCSWINSZ, winsize)
    proc = subprocess.Popen(args, stdin=slave, stdout=slave, stderr=slave, close_fds=True)
    os.close(slave)
    time.sleep(0.6)
    try:
        proc.wait(timeout=1)
    except:
        proc.terminate()
        try:
            proc.wait(timeout=1)
        except:
            proc.kill()
    data=b''
    while True:
        r,_,_ = select.select([master], [], [], 0.1)
        if not r:
            break
        try:
            chunk=os.read(master, 4096)
            if not chunk:
                break
            data+=chunk
        except Exception as e:
            break
    os.close(master)
    return data, proc.returncode

for m in ["ansible","download"]:
    for cols in [80, 120, 40]:
        data, rc = run_with_pty_winsize(["./executable","-m",m,"--speed-factor","100","--exit-after-time","200ms","--instant-print-lines","2"], cols=cols)
        print(f"{m} cols={cols} rc={rc} len={len(data)}")
        print(data[:600].decode(errors='ignore').replace('\r','\\r\n')[:600])
        print("---")
