            return "OK"
        elif proc.returncode==2:
            return f"ERR:{proc.stderr.splitlines()[0][:120]}"
        else:
            return f"RC{proc.returncode}"
    except subprocess.TimeoutExpired:
        return "TIMEOUT_OK"

