        "m" | "min" | "mins" | "minute" | "minutes" |
        "h" | "hr" | "hrs" | "hour" | "hours" |
        "d" | "day" | "days" |
        "w" | "week" | "weeks" | "wk" | "wks" |
        "M" | "month" | "months" |
        "y" | "year" | "years" | "yr" | "yrs"
    )
}

fn unit_to_duration(unit: &str, value: f64) -> Duration {
    // Use approximate durations: month = 30.44 days? But fundu likely uses 30 days? Let's check jiff vs humantime? However original genact uses fundu which defines month as 30.44 days? For duration parsing, the exact value matters for exit-after-time precision? But for our needs, any approximate is okay as long as it parses? However to be safe, we should define month as 30 days and year as 365 days, similar to fundu?
    // Let's look at fundu docs: fundu defines month as 30.44 days (2629746 seconds) and year as 365.25 days? Actually we can approximate.
    // For exit-after-time, it just needs to be >0 to trigger after correct wall time. Using different factor won't matter much for tests unless they check exact duration.
    // We'll use: ns = 1ns, us=1us, ms=1ms, s=1s, m=60s, h=3600s, d=86400s, w=604800s, M=2629746s (30.44d), y=31556952s (365.2425d)
    let secs = match unit {
        "ns" | "nsec" | "nanos" => value * 1e-9,
        "us" | "µs" | "usec" => value * 1e-6,
        "ms" | "msec" | "millis" => value * 1e-3,
        "s" | "sec" | "secs" | "second" | "seconds" => value,
        "m" | "min" | "mins" | "minute" | "minutes" => value * 60.0,
        "h" | "hr" | "hrs" | "hour" | "hours" => value * 3600.0,
        "d" | "day" | "days" => value * 86400.0,
        "w" | "week" | "weeks" | "wk" | "wks" => value * 604800.0,
        "M" | "month" | "months" => value * 2629746.0, // 30.44 days
        "y" | "year" | "years" | "yr" | "yrs" => value * 31556952.0, // 365.2425 days
        _ => value,
    };
    Duration::from_secs_f64(secs)
}
