use std::time::Duration;

pub fn parse_duration(s: &str) -> Result<Duration, String> {
    if s.is_empty() {
        return Err("value was empty".to_string());
    }
    if s.trim().is_empty() {
        return Err("value was empty".to_string());
    }
    let bytes = s.as_bytes();
    let len = bytes.len();

    let mut total_duration = Duration::from_secs(0);
    let mut any_parsed = false;
    let mut idx = 0usize;

    // Check first non-whitespace char is digit, otherwise expected number at 0
    let mut first_non_ws = 0;
    while first_non_ws < len && (bytes[first_non_ws] == b' ' || bytes[first_non_ws] == b'\t' || bytes[first_non_ws] == b'\n' || bytes[first_non_ws] == b'\r') {
        first_non_ws += 1;
    }
    if first_non_ws < len && !bytes[first_non_ws].is_ascii_digit() {
        return Err("expected number at 0".to_string());
    }

    idx = 0;
    while idx < len {
        // Skip whitespace between entries
        while idx < len && (bytes[idx] == b' ' || bytes[idx] == b'\t' || bytes[idx] == b'\n' || bytes[idx] == b'\r') {
            idx += 1;
        }
        if idx >= len {
            break;
        }
        // Expect number
        let num_start = idx;
        if !bytes[idx].is_ascii_digit() {
            return Err(format!("expected number at {}", num_start));
        }
        // Parse digits before dot
        while idx < len && bytes[idx].is_ascii_digit() {
            idx += 1;
        }
        // Optional dot fraction
        if idx < len && bytes[idx] == b'.' {
            if idx + 1 >= len || !bytes[idx+1].is_ascii_digit() {
                return Err(format!("invalid character at {}", idx));
            }
            idx += 1; // skip dot
            while idx < len && bytes[idx].is_ascii_digit() {
                idx += 1;
            }
        }
        let num_end = idx;
        let num_str = &s[num_start..num_end];
        // Check for invalid chars like comma immediately after number without whitespace? Actually number parsing stops at comma, then we will handle unit.
        // Skip whitespace between number and unit
        while idx < len && (bytes[idx] == b' ' || bytes[idx] == b'\t' || bytes[idx] == b'\n' || bytes[idx] == b'\r') {
            idx += 1;
        }
        if idx >= len {
            return Err("time unit needed, for example 5sec or 5ms".to_string());
        }
        if bytes[idx].is_ascii_digit() {
            return Err("time unit needed, for example 5sec or 5ms".to_string());
        }
        // Peek char
        let remaining = &s[idx..];
        let ch = remaining.chars().next().unwrap();
        if ch == ',' || ch == ';' || ch == '_' || ch == '.' || ch == '+' || ch == '-' || ch == '/' || ch == '\\' || ch == ':' || ch == '"' || ch == '\'' {
            return Err(format!("invalid character at {}", idx));
        }
        if ch.is_whitespace() {
            idx += ch.len_utf8();
            continue;
        }
        // Collect unit
        let mut unit_end = idx;
        let mut unit_str = String::new();
        for c in remaining.chars() {
            if c.is_ascii_digit() || c.is_whitespace() {
                break;
            }
            if c == ',' || c == ';' || c == '.' || c == '_' || c == ':' {
                break;
            }
            if c.is_ascii_alphabetic() || c == 'µ' {
                unit_str.push(c);
                unit_end += c.len_utf8();
            } else {
                return Err(format!("invalid character at {}", idx));
            }
        }
        if unit_str.is_empty() {
            return Err(format!("invalid character at {}", idx));
        }
        idx = unit_end;
        if !is_valid_unit(&unit_str) {
            return Err(format!("unknown time unit \"{}\", supported units: ns, us/µs, ms, sec, min, hours, days, weeks, months, years (and few variations)", unit_str));
        }
        let num: f64 = num_str.parse().map_err(|_| format!("invalid character at {}", num_start))?;
        let unit_duration = unit_to_duration(&unit_str, num);
        total_duration += unit_duration;
        any_parsed = true;
    }
    if !any_parsed {
        return Err("value was empty".to_string());
    }
    Ok(total_duration)
}

fn is_valid_unit(u: &str) -> bool {
    matches!(u,
        "ns" | "nsec" | "nanos" |
        "us" | "µs" | "usec" |
        "ms" | "msec" | "millis" |
        "s" | "sec" | "secs" | "second" | "seconds" |
        "m" | "min" | "mins" | "minute" | "minutes" |
        "h" | "hr" | "hrs" | "hour" | "hours" |
        "d" | "day" | "days" |
        "w" | "week" | "weeks" | "wk" | "wks" |
        "M" | "month" | "months" |
        "y" | "year" | "years" | "yr" | "yrs"
    )
}

fn unit_to_duration(unit: &str, value: f64) -> Duration {
    let secs = match unit {
        "ns" | "nsec" | "nanos" => value * 1e-9,
        "us" | "µs" | "usec" => value * 1e-6,
        "ms" | "msec" | "millis" => value * 1e-3,
        "s" | "sec" | "secs" | "second" | "seconds" => value,
        "m" | "min" | "mins" | "minute" | "minutes" => value * 60.0,
        "h" | "hr" | "hrs" | "hour" | "hours" => value * 3600.0,
        "d" | "day" | "days" => value * 86400.0,
        "w" | "week" | "weeks" | "wk" | "wks" => value * 604800.0,
        "M" | "month" | "months" => value * 2629746.0,
        "y" | "year" | "years" | "yr" | "yrs" => value * 31556952.0,
        _ => value,
    };
    Duration::from_secs_f64(secs)
}
