use clap::{Arg, Command, value_parser};
use clap_complete::{generate, Shell};
use rand::seq::SliceRandom;
use std::time::{Duration, Instant};
use std::io::Write;

mod duration;
mod io;
mod modules;

#[derive(Copy, Clone, PartialEq, Eq, Debug)]
enum Module {
    Ansible,
    Bootlog,
    Botnet,
    Bruteforce,
    Cargo,
    Cc,
    Composer,
    Cryptomining,
    DockerBuild,
    DockerImageRm,
    Download,
    Julia,
    KernelCompile,
    Memdump,
    Mkinitcpio,
    Rkhunter,
    Simcity,
    Terraform,
    Uv,
    Weblog,
    Wpt,
}

impl std::fmt::Display for Module {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let s = match self {
            Module::Ansible => "ansible",
            Module::Bootlog => "bootlog",
            Module::Botnet => "botnet",
            Module::Bruteforce => "bruteforce",
            Module::Cargo => "cargo",
            Module::Cc => "cc",
            Module::Composer => "composer",
            Module::Cryptomining => "cryptomining",
            Module::DockerBuild => "docker_build",
            Module::DockerImageRm => "docker_image_rm",
            Module::Download => "download",
            Module::Julia => "julia",
            Module::KernelCompile => "kernel_compile",
            Module::Memdump => "memdump",
            Module::Mkinitcpio => "mkinitcpio",
            Module::Rkhunter => "rkhunter",
            Module::Simcity => "simcity",
            Module::Terraform => "terraform",
            Module::Uv => "uv",
            Module::Weblog => "weblog",
            Module::Wpt => "wpt",
        };
        write!(f, "{}", s)
    }
}

fn module_from_str(s: &str) -> Option<Module> {
    match s {
        "ansible" => Some(Module::Ansible),
        "bootlog" => Some(Module::Bootlog),
        "botnet" => Some(Module::Botnet),
        "bruteforce" => Some(Module::Bruteforce),
        "cargo" => Some(Module::Cargo),
        "cc" => Some(Module::Cc),
        "composer" => Some(Module::Composer),
        "cryptomining" => Some(Module::Cryptomining),
        "docker_build" => Some(Module::DockerBuild),
        "docker_image_rm" => Some(Module::DockerImageRm),
        "download" => Some(Module::Download),
        "julia" => Some(Module::Julia),
        "kernel_compile" => Some(Module::KernelCompile),
        "memdump" => Some(Module::Memdump),
        "mkinitcpio" => Some(Module::Mkinitcpio),
        "rkhunter" => Some(Module::Rkhunter),
        "simcity" => Some(Module::Simcity),
        "terraform" => Some(Module::Terraform),
        "uv" => Some(Module::Uv),
        "weblog" => Some(Module::Weblog),
        "wpt" => Some(Module::Wpt),
        _ => None,
    }
}

fn all_modules() -> Vec<Module> {
    vec![
        Module::Ansible,
        Module::Bootlog,
        Module::Botnet,
        Module::Bruteforce,
        Module::Cargo,
        Module::Cc,
        Module::Composer,
        Module::Cryptomining,
        Module::DockerBuild,
        Module::DockerImageRm,
        Module::Download,
        Module::Julia,
        Module::KernelCompile,
        Module::Memdump,
        Module::Mkinitcpio,
        Module::Rkhunter,
        Module::Simcity,
        Module::Terraform,
        Module::Uv,
        Module::Weblog,
        Module::Wpt,
    ]
}

fn possible_modules_values() -> Vec<&'static str> {
    vec!["ansible","bootlog","botnet","bruteforce","cargo","cc","composer","cryptomining","docker_build","docker_image_rm","download","julia","kernel_compile","memdump","mkinitcpio","rkhunter","simcity","terraform","uv","weblog","wpt"]
}

fn parse_speed_factor(s: &str) -> Result<f64, String> {
    let v: f64 = s.parse().map_err(|_| "invalid float literal".to_string())?;
    if v <= 0.01 {
        return Err("Speed factor must be larger than 0.01".to_string());
    }
    Ok(v)
}

fn parse_instant(s: &str) -> Result<u64, String> {
    s.parse::<u64>().map_err(|e| e.to_string())
}

fn parse_exit_modules(s: &str) -> Result<u64, String> {
    let v: u64 = s.parse().map_err(|e: std::num::ParseIntError| e.to_string())?;
    if v == 0 {
        return Err("Must be larger than 0".to_string());
    }
    Ok(v)
}

fn build_command() -> Command {
    Command::new("genact")
        .version("1.5.1")
        .about("A nonsense activity generator")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(Arg::new("list-modules").short('l').long("list-modules").help("List available modules").action(clap::ArgAction::SetTrue))
        .arg(Arg::new("modules").short('m').long("modules").value_name("MODULES").help("Run only these modules")
            .value_parser(possible_modules_values())
            .action(clap::ArgAction::Append))
        .arg(Arg::new("speed-factor").short('s').long("speed-factor").value_name("SPEED_FACTOR").help("Global speed factor").default_value("1").value_parser(parse_speed_factor))
        .arg(Arg::new("instant-print-lines").short('i').long("instant-print-lines").value_name("INSTANT_PRINT_LINES").help("Instantly print this many lines").default_value("0").value_parser(parse_instant))
        .arg(Arg::new("inhibit").long("inhibit").help("Keep the computer awake and the display on while genact is running").action(clap::ArgAction::SetTrue))
        .arg(Arg::new("exit-after-time").long("exit-after-time").value_name("EXIT_AFTER_TIME").help("Exit after running for this long (format example: 2h10min)").value_parser(duration::parse_duration))
        .arg(Arg::new("exit-after-modules").long("exit-after-modules").value_name("EXIT_AFTER_MODULES").help("Exit after running this many modules").value_parser(parse_exit_modules))
        .arg(Arg::new("print-completions").long("print-completions").value_name("shell").help("Generate completion file for a shell").value_parser(value_parser!(Shell)))
        .arg(Arg::new("print-manpage").long("print-manpage").help("Generate man page").action(clap::ArgAction::SetTrue))
        .arg(Arg::new("help").short('h').long("help").help("Print help").action(clap::ArgAction::SetTrue))
        .arg(Arg::new("version").short('V').long("version").help("Print version").action(clap::ArgAction::SetTrue))
        .author("Sven-Hendrik Haase <svenstaro@gmail.com>")
}

static HELP_TEXT: &str = "A nonsense activity generator\n\nUsage: {bin} [OPTIONS]\n\nOptions:\n  -l, --list-modules\n          List available modules\n  -m, --modules <MODULES>\n          Run only these modules [possible values: ansible, bootlog, botnet, bruteforce, cargo, cc,\n          composer, cryptomining, docker_build, docker_image_rm, download, julia, kernel_compile,\n          memdump, mkinitcpio, rkhunter, simcity, terraform, uv, weblog, wpt]\n  -s, --speed-factor <SPEED_FACTOR>\n          Global speed factor [default: 1]\n  -i, --instant-print-lines <INSTANT_PRINT_LINES>\n          Instantly print this many lines [default: 0]\n      --inhibit\n          Keep the computer awake and the display on while genact is running\n      --exit-after-time <EXIT_AFTER_TIME>\n          Exit after running for this long (format example: 2h10min)\n      --exit-after-modules <EXIT_AFTER_MODULES>\n          Exit after running this many modules\n      --print-completions <shell>\n          Generate completion file for a shell [possible values: bash, elvish, fish, powershell,\n          zsh]\n      --print-manpage\n          Generate man page\n  -h, --help\n          Print help\n  -V, --version\n          Print version\n";

fn print_help() {
    let bin = std::env::args().next().unwrap_or_else(|| "genact".to_string());
    let bin_name = std::path::Path::new(&bin).file_name().and_then(|s| s.to_str()).unwrap_or(&bin);
    let text = HELP_TEXT.replace("{bin}", bin_name);
    print!("{}", text);
}

fn main() {
    let cmd = build_command();
    let matches = cmd.clone().try_get_matches();
    let matches = match matches {
        Ok(m) => m,
        Err(e) => {
            // clap error handling: print error and exit with 2 (as original does)
            e.exit();
        }
    };

    if matches.get_flag("help") {
        print_help();
        return;
    }
    if matches.get_flag("version") {
        println!("genact 1.5.1");
        return;
    }

    if matches.get_flag("list-modules") {
        println!("Available modules:");
        for m in all_modules() {
            println!("  {}", m);
        }
        return;
    }

    if let Some(shell) = matches.get_one::<Shell>("print-completions") {
        let mut cmd = build_command();
        let bin_name = "genact";
        generate(*shell, &mut cmd, bin_name, &mut std::io::stdout());
        return;
    }

    if matches.get_flag("print-manpage") {
        let cmd = build_command();
        let man = clap_mangen::Man::new(cmd);
        let mut buffer: Vec<u8> = Vec::new();
        man.render(&mut buffer).expect("man render");
        std::io::stdout().write_all(&buffer).unwrap();
        return;
    }

    let inhibit = matches.get_flag("inhibit");
    if inhibit {
        println!("WARN: failed to set up idle inhibition: system: I/O error: No such file or directory (os error 2)");
        let _ = std::io::stdout().flush();
    }

    let speed_factor = *matches.get_one::<f64>("speed-factor").unwrap();
    let instant = *matches.get_one::<u64>("instant-print-lines").unwrap();

    let filtered: Vec<Module> = if let Some(vals) = matches.get_many::<String>("modules") {
        let mut uniq = Vec::new();
        for v in vals {
            if let Some(m) = module_from_str(v) {
                if !uniq.contains(&m) {
                    uniq.push(m);
                }
            }
        }
        uniq
    } else {
        all_modules()
    };

    let deadline = matches.get_one::<Duration>("exit-after-time").map(|d| Instant::now() + *d);
    let exit_after_modules = matches.get_one::<u64>("exit-after-modules").copied();

    let mut modules_run: u64 = 0;
    let mut rng = rand::thread_rng();

    loop {
        if let Some(dl) = deadline {
            if Instant::now() >= dl {
                break;
            }
        }
        if let Some(limit) = exit_after_modules {
            if modules_run >= limit {
                break;
            }
        }
        let choice = *filtered.choose(&mut rng).unwrap();
        let should_continue = modules::run_module(choice, speed_factor, instant, deadline);
        modules_run += 1;
        if !should_continue {
            break;
        }
        if let Some(limit) = exit_after_modules {
            if modules_run >= limit {
                break;
            }
        }
        if let Some(dl) = deadline {
            if Instant::now() >= dl {
                break;
            }
        }
    }
}
