import subprocess, pty, os, struct, fcntl, termios, time, select

def run_with_pty(orig, m, cols=80):
    master, slave = pty.openpty()
    winsize = struct.pack("HHHH", 24, cols, 0, 0)
    fcntl.ioctl(slave, termios.TIOCSWINSZ, winsize)
    proc = subprocess.Popen([orig,"-m",m,"--speed-factor","200","--exit-after-modules","1"], stdin=slave, stdout=slave, stderr=slave, close_fds=True)
    os.close(slave)
    time.sleep(1.5)
    # Try wait
    try:
        proc.wait(timeout=1)
    except:
        proc.terminate()
        try: proc.wait(timeout=1)
        except: proc.kill()
    data=b''
    while True:
        r,_,_=select.select([master],[],[],0.05)
        if not r: break
        try:
            c=os.read(master,8192)
            if not c: break
            data+=c
        except: break
    os.close(master)
    return data.decode(errors='ignore')

for m in ["ansible","download","bootlog","memdump","botnet","docker_build","simcity","uv","wpt"]:
