use rand::Rng;
use std::time::{Duration, Instant};
use crate::io::get_terminal_width;
pub fn run(speed_factor: f64, instant_lines: u64, deadline: Option<Instant>) -> bool {
    let width = get_terminal_width();
    if width < 55 {
        let base = Duration::from_millis(12);
        let mut instant_remaining = instant_lines;
        let total = 40 + rand::random::<u8>() as usize % 20;
        for _ in 0..total {
            if crate::modules::should_exit(deadline) {
                println!("Saving work to disk...");
                return false;
            }
            println!("Terminal too small to display download progress");
            if crate::modules::should_exit(deadline) { println!("Saving work to disk..."); return false; }
            if instant_remaining>0 { instant_remaining-=1; } else { std::thread::sleep(crate::modules::sleep_with_speed(base, speed_factor)); }
        }
        println!("Saving work to disk...");
        return true;
    }
    let mut rng = rand::thread_rng();
    let base = Duration::from_millis(15);
    let mut instant_remaining = instant_lines;
    // Simplified finite download: just print 100 lines of progress then saving
    let total_lines = 100 + rng.gen_range(0..50);
    for i in 0..total_lines {
        if crate::modules::should_exit(deadline) {
            println!("Saving work to disk...");
            return false;
        }
        let fname = if i % 20 == 0 { "HalPhyRf_8723B.f" } else if i % 3 == 0 { "e.png" } else { "atmel-ebi.tar.xz" };
        let bar_width = if width > 50 { width - 50 } else { 20 };
        let progress = (i * 100 / total_lines) as u8;
        let filled = (progress as usize * bar_width / 100) as usize;
        let bar_filled = "\u{2588}".repeat(filled);
        let bar_empty = " ".repeat(bar_width - filled);
        let size = rng.gen_range(1.0..5.0);
        let speed = rng.gen_range(15.0..99.0);
        let eta = rng.gen_range(0..10);
        print!("\u{1b}[2K\u{1b}[0G{} {:3}%[{}{}] {:.2}MiB    {:.2}MiB/s   eta {}s", fname, progress, bar_filled, bar_empty, size, speed, eta);
        use std::io::Write;
        std::io::stdout().flush().unwrap();
        if i % 30 == 29 {
            println!();
        }
        if crate::modules::should_exit(deadline) {
            println!();
            println!("Saving work to disk...");
            return false;
        }
        if instant_remaining>0 {
            instant_remaining-=1;
        } else {
            std::thread::sleep(crate::modules::sleep_with_speed(base, speed_factor));
        }
    }
    println!();
    println!("Saving work to disk...");
    true
}
